WITH latest AS (SELECT id, carrier, shipped_date, status FROM shipments QUALIFY RANK() OVER (PARTITION BY order_id ORDER BY delivered_date DESC) = 1), filtered AS (SELECT *, CONCAT_WS('-', carrier, status) AS carrier_status_key, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM latest WHERE carrier IS NOT NULL), enriched AS (SELECT id, shipped_date, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY shipped_date DESC, id) AS row_seq, FIRST_VALUE(carrier, TRUE) OVER (ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_carrier, LAST_VALUE(carrier) IGNORE NULLS OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier, FIRST_VALUE(carrier, TRUE) OVER (PARTITION BY carrier ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_carrier_2 FROM filtered WHERE MONTH(shipped_date) IN (2, 5, 8)), enriched_shipments AS (SELECT *, LAG(row_seq) OVER w_grp AS prev_row_seq, ROW_NUMBER() OVER w_grp AS event_seq, NTILE(3) OVER (ORDER BY row_seq DESC, id) AS row_seq_bucket FROM enriched WINDOW w_grp AS (ORDER BY row_seq, id)), filtered_shipments AS (SELECT id, shipped_date, row_seq, first_known_carrier, last_known_carrier, first_known_carrier_2, prev_row_seq, event_seq, row_seq_bucket, GREATEST(prev_row_seq, row_seq) AS greatest_prev_row_seq_row_seq FROM enriched_shipments WHERE shipped_date > DATE '2023-03-04' AND prev_row_seq > 5), metrics AS (SELECT id, shipped_date, first_known_carrier, greatest_prev_row_seq_row_seq, COUNT(prev_row_seq) OVER w_ordered AS last7_count_prev_row_seq, SUM(prev_row_seq) OVER w_ordered AS last7_sum_prev_row_seq, AVG(prev_row_seq) OVER w_ordered AS last7_avg_prev_row_seq, MAX(prev_row_seq) OVER w_ordered AS last7_max_prev_row_seq, LAST_VALUE(event_seq, TRUE) OVER (ORDER BY event_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_event_seq FROM filtered_shipments WINDOW w_ordered AS (ORDER BY row_seq, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT CASE WHEN last7_max_prev_row_seq >= 7.0 THEN 'LARGE' ELSE 'SMALL' END AS last7_max_prev_row_seq_tier, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(greatest_prev_row_seq_row_seq, 0.9) AS greatest_prev_row_seq_row_seq_p90 FROM metrics GROUP BY 1 ORDER BY distinct_ids DESC;
